def Q(prompt, options, right, whys, steps, concept, skill, hint, feedback="", diagram="", diagram_alt=""):
    """4-option MC. `right` = index of the correct option; `whys[i]` explains wrong option i (use "" at `right`)."""
    return MC(prompt, [C(t, correct=(i == right), why="" if i == right else whys[i]) for i, t in enumerate(options)],
              steps=[S(f"Step {n}", text=t) for n, t in enumerate(steps, 1)] if len(steps) > 1 else [S("Answer", text=steps[0])],
              concept=concept, skill=skill, hint=hint, feedback=feedback, diagram=diagram, diagram_alt=diagram_alt)


def N(prompt, answer, steps, tol, unit, concept, skill, hint, feedback="", diagram="", diagram_alt=""):
    return NUM(prompt, answer, steps=[S(f"Step {n}", text=t) for n, t in enumerate(steps, 1)] if len(steps) > 1 else [S("Answer", text=steps[0])],
               tolerance=tol, unit=unit, concept=concept, skill=skill, hint=hint, feedback=feedback, diagram=diagram, diagram_alt=diagram_alt)


